// Runtime env for local development (should match NEXT_PUBLIC_* values from .env.local)
// Include only non-sensitive NEXT_PUBLIC_* values here.
// In production, this file is generated by entrypoint.sh at runtime.
window.__ENV__ = {
  NEXT_PUBLIC_API_BASE: "http://localhost:8001/api",
  NEXT_PUBLIC_ENABLE_LOGGING: "true",
  NEXT_PUBLIC_APP_VERSION: "dev",
};
// Signal that the runtime env has been injected
window.dispatchEvent(new Event('env-ready'));
